/// <summary>
/// DebuC 16.06.23
/// </summary>
/// <returns>InventQtyAvailOrdered</returns>
display InventQtyAvailOrdered   availECP()
{
    InventItemType          inventItemType  = InventItemType::newItemId(this.ItemId);
    InventQtyAvailOrdered   tmpQty;
    ;
    this.setInventSum();

    if (inventItemType.isServiceItem())
    {
        return 0;
    }

    tmpQty = this.availPhysical() + this.ordered() + this.arrived() - this.reservOrdered() - this.onOrder();

    return tmpQty;
}
